import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import EnariaLogo from "./EnariaLogo";

interface SplashScreenProps {
  onComplete: () => void;
  duration?: number;
}

type AnimationPhase =
  | "blackout"
  | "entering"
  | "revealing"
  | "glitching"
  | "exiting";

export default function SplashScreen({
  onComplete,
  duration = 6000,
}: SplashScreenProps) {
  const [phase, setPhase] = useState<AnimationPhase>("blackout");

  useEffect(() => {
    const timer1 = setTimeout(() => setPhase("entering"), 500);
    const timer2 = setTimeout(() => setPhase("revealing"), 2000);
    const timer3 = setTimeout(() => setPhase("glitching"), 4000);
    const timer4 = setTimeout(() => setPhase("exiting"), 5000);
    const timer5 = setTimeout(() => onComplete(), duration);

    return () => {
      clearTimeout(timer1);
      clearTimeout(timer2);
      clearTimeout(timer3);
      clearTimeout(timer4);
      clearTimeout(timer5);
    };
  }, [onComplete, duration]);

  return (
    <AnimatePresence>
      <motion.div
        className="fixed inset-0 z-50 overflow-hidden"
        initial={{ opacity: 1 }}
        exit={{ opacity: 1 }}
        transition={{ duration: 1, ease: "easeInOut" }}
      >
        {/* Fondo negro con recorte del texto para ver la landing detrás */}
        <motion.svg
          className="absolute inset-0 w-full h-full"
          initial={{ opacity: 1, scale: 1 }}
          animate={{
            opacity: phase === "exiting" ? 1 : 1,
            scale: phase === "exiting" ? 8.15 : 1,
          }}
          transition={{ duration: 1.2, ease: "easeOut" }}
        >
          <defs>
            <mask id="logoMask">
              <rect width="100%" height="100%" fill="white" />
              <svg
                x="50%"
                y="50%"
                width="600"
                height="100"
                viewBox="0 0 146 24"
                transform="translate(-300,-50)"
              >
                <g fill="black" stroke="white" strokeWidth="1">
                  <path d="M24.236 23.7652H11.831C5.30716 23.7652 0 18.4349 0 11.8826C0 5.33027 5.30716 0 11.831 0H24.236V5.37218H11.831C8.25662 5.37218 5.34888 8.29258 5.34888 11.8826C5.34888 15.4726 8.25662 18.393 11.831 18.393H24.236V23.7652Z" />
                  <path d="M16.7977 9.48438H10.6851V14.281H16.7977V9.48438Z" />
                  <path d="M52.3017 23.766H46.9528V12.1699C46.9528 8.42171 43.9165 5.37218 40.1845 5.37218C36.4526 5.37218 33.4163 8.42171 33.4163 12.1699V23.766H28.0674V12.1699C28.0674 5.4594 33.5031 0 40.1845 0C46.8659 0 52.3017 5.4594 52.3017 12.1699V23.766Z" />
                  <path d="M83.0437 23.7652H67.9644C61.4405 23.7652 56.1333 18.4349 56.1333 11.8826C56.1333 5.33027 61.4405 0 67.9644 0H71.2135C77.7374 0 83.0446 5.33027 83.0446 11.8826V23.7652H83.0437ZM67.9644 5.37303C64.3899 5.37303 61.4822 8.29344 61.4822 11.8834C61.4822 15.4734 64.3899 18.3938 67.9644 18.3938H77.6948V11.8834C77.6948 8.29344 74.7871 5.37303 71.2127 5.37303H67.9635H67.9644Z" />
                  <path d="M92.2253 23.766H86.8765V12.1699C86.8765 5.4594 92.3122 0 98.9936 0H107.415V5.37218H98.9936C95.2617 5.37218 92.2253 8.42171 92.2253 12.1699V23.766Z" />
                  <path d="M116.595 0.00390625H111.246V23.7622H116.595V0.00390625Z" />
                  <path d="M146 23.7652H132.257C125.733 23.7652 120.426 18.4349 120.426 11.8826C120.426 5.33027 125.733 0 132.257 0H134.169C140.693 0 146 5.33027 146 11.8826V23.7652ZM132.257 5.37303C128.683 5.37303 125.775 8.29344 125.775 11.8834C125.775 15.4734 128.683 18.3938 132.257 18.3938H140.651V11.8834C140.651 8.29344 137.743 5.37303 134.169 5.37303H132.257Z" />
                </g>
              </svg>
            </mask>
          </defs>
          <rect width="100%" height="100%" fill="black" mask="url(#logoMask)" />
        </motion.svg>

        {/* Cinematic Bars */}
        <motion.div
          className="absolute top-0 left-0 w-full h-16 bg-black z-40"
          initial={{ y: -64 }}
          animate={{ y: phase === "blackout" ? -64 : 0 }}
          transition={{ duration: 0.8, ease: "easeOut" }}
        />
        <motion.div
          className="absolute bottom-0 left-0 w-full h-16 bg-black z-40"
          initial={{ y: 64 }}
          animate={{ y: phase === "blackout" ? 64 : 0 }}
          transition={{ duration: 0.8, ease: "easeOut" }}
        />

        {/* Matrix-like particles */}
        <div className="absolute inset-0 overflow-hidden">
          {[...Array(100)].map((_, i) => (
            <motion.div
              key={i}
              className="absolute w-0.5 h-0.5 bg-accent-cyan rounded-full"
              initial={{
                x: Math.random() * window.innerWidth,
                y: -10,
                opacity: 0,
              }}
              animate={{
                y: window.innerHeight + 10,
                opacity:
                  phase === "revealing" || phase === "glitching"
                    ? [0, 1, 0]
                    : 0,
              }}
              transition={{
                duration: Math.random() * 3 + 2,
                delay: Math.random() * 2,
                repeat: Infinity,
                ease: "linear",
              }}
            />
          ))}
        </div>

        {/* Glitch overlay */}
        {phase === "glitching" && (
          <motion.div
            className="absolute inset-0 bg-gradient-to-r from-transparent via-accent-cyan/10 to-transparent"
            animate={{
              x: [-100, 100, -100],
              opacity: [0, 0.3, 0],
            }}
            transition={{
              duration: 0.3,
              repeat: 3,
              ease: "easeInOut",
            }}
          />
        )}

        {/* Main Content Container */}
        <div className="absolute inset-0 flex items-center justify-center">
          {/* Background Glow */}
          <motion.div
            className="absolute w-96 h-96 bg-gradient-radial from-accent-cyan/30 via-accent-cyan/10 to-transparent rounded-full blur-3xl"
            initial={{ scale: 0, opacity: 0 }}
            animate={{
              scale: phase === "revealing" || phase === "glitching" ? 1.5 : 0,
              opacity: phase === "revealing" || phase === "glitching" ? 0.6 : 0,
            }}
            transition={{ duration: 2, ease: "easeOut" }}
          />

          {/* Main Text Container */}
          <motion.div
            className="relative z-10 text-center"
            initial={{ scale: 0.5, opacity: 0 }}
            animate={{
              scale: phase === "exiting" ? 1.25 : 1,
              opacity: 1,
              rotateX: phase === "glitching" ? [0, 5, -5, 0] : 0,
            }}
            transition={{
              duration: phase === "glitching" ? 0.2 : 1.2,
              ease: "easeOut",
              repeat: phase === "glitching" ? 2 : 0,
            }}
          >
            {/* ENARIA SVG */}
            <div className="relative">
              <motion.div
                className="flex justify-center items-center"
                initial={{ opacity: 0 }}
                animate={{ opacity: 0 }}
              />

              {/* Underline effect */}
              <motion.div
                className="absolute bottom-0 left-1/2 h-1 bg-gradient-to-r from-transparent via-accent-cyan to-transparent"
                initial={{ width: 0, x: "-50%" }}
                animate={{
                  width:
                    phase === "revealing" || phase === "glitching" ? "100%" : 0,
                  opacity:
                    phase === "revealing" || phase === "glitching" ? 1 : 0,
                }}
                transition={{ duration: 1.5, delay: 2.5 }}
              />
            </div>

            {/* Subtitle */}
            <motion.p
              className="text-xl md:text-3xl text-accent-cyan mt-8 font-light tracking-widest font-inter"
              initial={{ opacity: 0, y: 30, scale: 0.8 }}
              animate={{
                opacity: phase === "revealing" || phase === "glitching" ? 1 : 0,
                y: phase === "revealing" || phase === "glitching" ? 0 : 30,
                scale: phase === "revealing" || phase === "glitching" ? 1 : 0.8,
              }}
              transition={{ duration: 1.2, delay: 3 }}
            >
              IA para Trading en México
            </motion.p>

            {/* Loading indicator */}
            <motion.div
              className="mt-12 flex justify-center"
              initial={{ opacity: 0 }}
              animate={{ opacity: phase === "revealing" ? 1 : 0 }}
              transition={{ delay: 3.5 }}
            >
              <div className="flex space-x-2">
                {[...Array(3)].map((_, i) => (
                  <motion.div
                    key={i}
                    className="w-2 h-2 bg-accent-cyan rounded-full"
                    animate={{
                      scale: [1, 1.5, 1],
                      opacity: [0.5, 1, 0.5],
                    }}
                    transition={{
                      duration: 1,
                      delay: i * 0.2,
                      repeat: Infinity,
                      ease: "easeInOut",
                    }}
                  />
                ))}
              </div>
            </motion.div>
          </motion.div>
        </div>

        {/* Fade out al salir */}
      </motion.div>
    </AnimatePresence>
  );
}
