import { useState, useEffect, useRef } from "react";
import { motion } from "framer-motion";
import { ArrowRight, TrendingUp, BarChart3, Zap, Eye } from "lucide-react";
import ParticleSystem3D from "../3d/ParticleSystem3D";
import EnariaLogo from "../animations/EnariaLogo";
import MainVideo from "../3d/CandlestickChart3D";

export default function Hero3DSection() {
  const [activeChart, setActiveChart] = useState<
    "candlestick" | "trend" | "particles"
  >("candlestick");
  const [isVisible, setIsVisible] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [lastSecond, setLastSecond] = useState<number>(0);

  const timeRef = useRef<number>(0);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  useEffect(() => {
    if (hovered) {
      intervalRef.current = setInterval(() => {
        setLastSecond((prev) => prev + 1);
      }, 1000);
      if (videoRef.current) {
        videoRef.current.play();
      }
    } else {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.currentTime = videoRef.current.currentTime;
      }
    }
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [hovered]);

  const chartVariants = {
    hidden: { opacity: 0, scale: 0.8, rotateY: -90 },
    visible: {
      opacity: 1,
      scale: 1,
      rotateY: 0,
      transition: { duration: 1.2, ease: "easeOut" },
    },
  };

  const textVariants = {
    hidden: { opacity: 0, y: 50 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.8, ease: "easeOut" },
    },
  };

  const buttonVariants = {
    hidden: { opacity: 0, scale: 0.8 },
    visible: {
      opacity: 1,
      scale: 1,
      transition: { duration: 0.6, delay: 0.8, ease: "easeOut" },
    },
    hover: {
      scale: 1.05,
      boxShadow: "0 0 30px rgba(0, 212, 255, 0.4)",
      transition: { duration: 0.2 },
    },
  };

  return (
    <section className="relative min-h-screen bg-gradient-to-br from-primary via-secondary to-primary overflow-hidden">
      {/* Background Particles */}
      <div className="absolute inset-0 opacity-30">
        <ParticleSystem3D
          width={window.innerWidth}
          height={window.innerHeight}
          particleCount={150}
          theme="network"
          interactive={false}
        />
      </div>

      {/* Gradient Overlays */}
      <div className="absolute inset-0 bg-gradient-radial from-accent-cyan/10 via-transparent to-transparent" />
      <div className="absolute inset-0 bg-gradient-to-t from-primary/80 via-transparent to-transparent" />

      <div className="relative z-10 container mx-auto px-6 py-20">
        <div className="grid lg:grid-cols-2 gap-12 items-center min-h-screen">
          {/* Left Content */}
          <motion.div
            className="space-y-8"
            initial="hidden"
            animate={isVisible ? "visible" : "hidden"}
          >
            {/* Badge */}
            <motion.div
              variants={textVariants}
              className="inline-flex items-center space-x-2 bg-accent-cyan/10 backdrop-blur-sm border border-accent-cyan/20 rounded-full px-3 py-1.5 sm:px-4 sm:py-2"
            >
              <Zap className="w-4 h-4 text-accent-cyan" />
              <span className="text-xs sm:text-sm font-medium text-accent-cyan">
                Inteligencia Artificial Avanzada
              </span>
            </motion.div>

            {/* Main Heading */}
            <motion.div
              id="hero-logo-anchor"
              variants={textVariants}
              className="space-y-4"
            >
              <EnariaLogo />

              <div className="w-20 sm:w-24 h-1 bg-gradient-to-r from-accent-cyan to-accent-orange rounded-full" />
            </motion.div>

            {/* Subtitle */}
            <motion.p
              variants={textVariants}
              className="text-base sm:text-lg lg:text-2xl text-gray-300 font-light leading-relaxed max-w-md sm:max-w-lg"
            >
              Revoluciona tu trading con{" "}
              <span className="text-accent-cyan font-medium">
                inteligencia artificial
              </span>{" "}
              diseñada para el mercado mundial.
            </motion.p>

            {/* Features */}
            <motion.div
              variants={textVariants}
              className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3 sm:gap-4"
            >
              {[
                {
                  icon: TrendingUp,
                  text: "Análisis Predictivo",
                  color: "text-accent-cyan",
                },
                {
                  icon: BarChart3,
                  text: "Trading Automatizado",
                  color: "text-accent-orange",
                },
              ].map((feature, index) => (
                <div
                  key={index}
                  className="flex items-center space-x-3 bg-white/5 backdrop-blur-sm rounded-lg p-3 sm:p-4 lg:p-5 border border-white/10"
                >
                  <feature.icon
                    className={`w-5 h-5 sm:w-6 sm:h-6 ${feature.color}`}
                  />
                  <span className="text-xs sm:text-base lg:text-lg font-medium text-white">
                    {feature.text}
                  </span>
                </div>
              ))}
            </motion.div>

            {/* CTA Buttons */}
            <motion.div
              variants={textVariants}
              className="flex flex-col sm:flex-row gap-4"
            >
              <motion.button
                onClick={() =>
                  window.open("https://app.enaria.io/r/cfe1b67b", "_blank")
                }
                variants={buttonVariants}
                whileHover="hover"
                className="group w-full sm:w-auto bg-gradient-to-r from-accent-cyan to-accent-cyan/80 text-black font-bold py-4 px-8 rounded-lg flex items-center justify-center space-x-2 transition-all duration-300"
              >
                <span>Obtener 1 mes de prueba</span>
                <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
              </motion.button>

              {/* Hover Card Container */}
              <div
                className="relative"
                onMouseEnter={() => setHovered(true)}
                onMouseLeave={() => setHovered(false)}
              >
                <Eye className="w-12 h-12 text-accent-cyan cursor-pointer" />

                <motion.div
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: hovered ? 1 : 0, y: hovered ? 0 : -10 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ duration: 0.2 }}
                  className={
                    hovered
                      ? "absolute bottom-full left-1/2 transform -translate-x-1/2 mb-3 w-96 bg-black/60 backdrop-blur-sm border border-accent-cyan/30 rounded-lg p-4 shadow-lg"
                      : "hidden"
                  }
                >
                  <h3 className="text-accent-cyan font-semibold mb-2">
                    Vista previa
                  </h3>
                  <video
                    ref={(el) => {
                      if (el) {
                        videoRef.current = el;
                        timeRef.current = el.currentTime;
                      }
                    }}
                    src={"./video/Crea tu cuenta en Enaria.mp4"}
                    onTimeUpdate={(
                      e: React.SyntheticEvent<HTMLVideoElement>
                    ) => {
                      const video = e.currentTarget;
                      if (video.currentTime >= video.duration) {
                        video.currentTime = 0;
                      }
                    }}
                    onLoadedMetadata={(
                      e: React.SyntheticEvent<HTMLVideoElement>
                    ) => {
                      const video = e.currentTarget;
                      if (timeRef.current !== null) {
                        video.currentTime = timeRef.current;
                      }
                    }}
                    onPlay={(e: React.SyntheticEvent<HTMLVideoElement>) => {
                      const video = e.currentTarget;
                      if (timeRef.current !== null) {
                        video.currentTime = timeRef.current;
                      }
                    }}
                  ></video>
                </motion.div>
              </div>
            </motion.div>

            {/* Stats */}
            <motion.div
              variants={textVariants}
              className="grid grid-cols-1 sm:grid-cols-3 gap-4 sm:gap-6 pt-8 border-t border-white/10"
            >
              {[
                { value: "98.7%", label: "Precisión IA" },
                { value: "24/7", label: "Operación Continua" },
                { value: "500+", label: "Comunidad Activa" },
              ].map((stat, index) => (
                <div key={index} className="text-center">
                  <div className="text-sm text-gray-400">{stat.label}</div>
                </div>
              ))}
            </motion.div>
          </motion.div>

          {/* Right Content - 3D Charts */}
          <motion.div
            className="relative"
            initial={false}
            animate={isVisible ? "visible" : "visible"}
            variants={chartVariants}
          >
            {/* 3D Chart Container */}
            <div className="relative bg-black/20 backdrop-blur-sm rounded-2xl border border-accent-cyan/20 overflow-hidden">
              <motion.div
                key={activeChart}
                initial={{ opacity: 1, scale: 1 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.3 }}
                className="w-full h-64 sm:h-80 md:h-[420px] lg:h-[500px]"
              >
                {activeChart === "candlestick" && (
                  <MainVideo url="https://www.youtube.com/embed/0YfFCiKg70E?si=IyT3SNrysL5-4qqN" />
                )}
              </motion.div>

              {/* Chart Info Overlay */}
              <div className="absolute bottom-4 left-4 right-4 bg-black/40 backdrop-blur-sm rounded-lg p-4 border border-white/10">
                <div className="flex justify-between items-center">
                  <div>
                    {activeChart === "candlestick" && (
                      <a
                        className="text-accent-cyan underline"
                        href="https://www.myfxbook.com/search/Enaria"
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        Cuenta Auditada MyFXBook
                      </a>
                    )}

                    <p className="text-gray-400 text-sm">
                      {activeChart === "candlestick" &&
                        "Rendimiento real y datos verificados"}
                    </p>
                  </div>
                  <div className="text-right">
                    <div className="text-accent-cyan font-bold text-lg">
                      {activeChart === "candlestick" && "Datos Reales"}
                    </div>
                    <div className="text-gray-400 text-sm">
                      {activeChart === "candlestick" && "Cuenta MyFXBook"}
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Floating Elements */}
            <motion.div
              className="absolute -top-8 -right-8 w-16 h-16 bg-accent-cyan/20 rounded-full blur-xl"
              animate={{
                scale: [1, 1.2, 1],
                opacity: [0.3, 0.6, 0.3],
              }}
              transition={{
                duration: 3,
                repeat: Infinity,
                ease: "easeInOut",
              }}
            />
            <motion.div
              className="absolute -bottom-8 -left-8 w-20 h-20 bg-accent-orange/20 rounded-full blur-xl"
              animate={{
                scale: [1.2, 1, 1.2],
                opacity: [0.4, 0.2, 0.4],
              }}
              transition={{
                duration: 4,
                repeat: Infinity,
                ease: "easeInOut",
              }}
            />
          </motion.div>
        </div>
      </div>

      {/* Scroll Indicator */}
      <motion.div
        className="absolute bottom-8 left-1/2 transform -translate-x-1/2"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 2, duration: 0.8 }}
      >
        <div className="flex flex-col items-center space-y-2 text-gray-400">
          <span className="text-sm">Descubre más</span>
          <motion.div
            className="w-6 h-10 border-2 border-gray-400 rounded-full flex justify-center"
            animate={{ y: [0, 5, 0] }}
            transition={{ duration: 1.5, repeat: Infinity }}
          >
            <motion.div
              className="w-1 h-3 bg-accent-cyan rounded-full mt-2"
              animate={{ opacity: [1, 0.3, 1] }}
              transition={{ duration: 1.5, repeat: Infinity }}
            />
          </motion.div>
        </div>
      </motion.div>
    </section>
  );
}
