import { useRef, useMemo } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei";
import * as THREE from "three";

interface ParticleSystem3DProps {
  particleCount?: number;
  width?: number;
  height?: number;
  interactive?: boolean;
  theme?: "trading" | "data" | "network";
}

// Trading Particles Component
function TradingParticles({ count = 300 }: { count: number }) {
  const particlesRef = useRef<THREE.Points>(null);
  const velocitiesRef = useRef<Float32Array>();

  const { positions, colors, sizes } = useMemo(() => {
    const positions = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);
    const sizes = new Float32Array(count);
    const velocities = new Float32Array(count * 3);

    for (let i = 0; i < count; i++) {
      // Positions
      positions[i * 3] = (Math.random() - 0.5) * 10;
      positions[i * 3 + 1] = (Math.random() - 0.5) * 10;
      positions[i * 3 + 2] = (Math.random() - 0.5) * 10;

      // Colors (trading theme: cyan and orange)
      const isCyan = Math.random() > 0.5;
      const color = isCyan
        ? new THREE.Color("#00D4FF")
        : new THREE.Color("#FF6B35");
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;

      // Sizes
      sizes[i] = Math.random() * 0.05 + 0.01;

      // Velocities
      velocities[i * 3] = (Math.random() - 0.5) * 0.02;
      velocities[i * 3 + 1] = (Math.random() - 0.5) * 0.02;
      velocities[i * 3 + 2] = (Math.random() - 0.5) * 0.02;
    }

    velocitiesRef.current = velocities;
    return { positions, colors, sizes };
  }, [count]);

  useFrame((state) => {
    if (particlesRef.current && velocitiesRef.current) {
      const positions = particlesRef.current.geometry.attributes.position
        .array as Float32Array;
      const velocities = velocitiesRef.current;

      for (let i = 0; i < count; i++) {
        // Update positions
        positions[i * 3] += velocities[i * 3];
        positions[i * 3 + 1] += velocities[i * 3 + 1];
        positions[i * 3 + 2] += velocities[i * 3 + 2];

        // Boundary check and reset
        if (Math.abs(positions[i * 3]) > 5) {
          positions[i * 3] = (Math.random() - 0.5) * 10;
          velocities[i * 3] = (Math.random() - 0.5) * 0.02;
        }
        if (Math.abs(positions[i * 3 + 1]) > 5) {
          positions[i * 3 + 1] = (Math.random() - 0.5) * 10;
          velocities[i * 3 + 1] = (Math.random() - 0.5) * 0.02;
        }
        if (Math.abs(positions[i * 3 + 2]) > 5) {
          positions[i * 3 + 2] = (Math.random() - 0.5) * 10;
          velocities[i * 3 + 2] = (Math.random() - 0.5) * 0.02;
        }
      }

      particlesRef.current.geometry.attributes.position.needsUpdate = true;
      particlesRef.current.rotation.y = state.clock.elapsedTime * 0.05;
    }
  });

  return (
    <points ref={particlesRef}>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          count={count}
          array={positions}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-color"
          count={count}
          array={colors}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-size"
          count={count}
          array={sizes}
          itemSize={1}
        />
      </bufferGeometry>
      <pointsMaterial
        transparent
        opacity={0.8}
        sizeAttenuation
        vertexColors
        blending={THREE.AdditiveBlending}
      />
    </points>
  );
}

// Data Flow Particles
function DataFlowParticles({ count = 200 }: { count: number }) {
  const particlesRef = useRef<THREE.Points>(null);

  const { positions, colors } = useMemo(() => {
    const positions = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);

    for (let i = 0; i < count; i++) {
      // Create flowing data streams
      const angle = (i / count) * Math.PI * 2;
      const radius = 2 + Math.random() * 3;

      positions[i * 3] = Math.cos(angle) * radius;
      positions[i * 3 + 1] = (Math.random() - 0.5) * 8;
      positions[i * 3 + 2] = Math.sin(angle) * radius;

      // Data stream colors (more cyan for data)
      const color = new THREE.Color("#00D4FF");
      color.lerp(new THREE.Color("#FFFFFF"), Math.random() * 0.3);
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }

    return { positions, colors };
  }, [count]);

  useFrame((state) => {
    if (particlesRef.current) {
      const positions = particlesRef.current.geometry.attributes.position
        .array as Float32Array;

      for (let i = 0; i < count; i++) {
        // Move particles upward in streams
        positions[i * 3 + 1] += 0.02;

        // Reset when reaching top
        if (positions[i * 3 + 1] > 4) {
          positions[i * 3 + 1] = -4;
        }

        // Add some wave motion
        positions[i * 3] += Math.sin(state.clock.elapsedTime + i * 0.1) * 0.001;
        positions[i * 3 + 2] +=
          Math.cos(state.clock.elapsedTime + i * 0.1) * 0.001;
      }

      particlesRef.current.geometry.attributes.position.needsUpdate = true;
    }
  });

  return (
    <points ref={particlesRef}>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          count={count}
          array={positions}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-color"
          count={count}
          array={colors}
          itemSize={3}
        />
      </bufferGeometry>
      <pointsMaterial
        size={0.02}
        transparent
        opacity={0.7}
        sizeAttenuation
        vertexColors
        blending={THREE.AdditiveBlending}
      />
    </points>
  );
}

// Network Connection Lines
function NetworkConnections() {
  const linesRef = useRef<THREE.Group>(null);

  const connections = useMemo(() => {
    const lines = [];
    const nodeCount = 20;
    const nodes = [];

    // Generate nodes
    for (let i = 0; i < nodeCount; i++) {
      nodes.push({
        x: (Math.random() - 0.5) * 8,
        y: (Math.random() - 0.5) * 8,
        z: (Math.random() - 0.5) * 8,
      });
    }

    // Generate connections
    for (let i = 0; i < nodeCount; i++) {
      for (let j = i + 1; j < nodeCount; j++) {
        const distance = Math.sqrt(
          Math.pow(nodes[i].x - nodes[j].x, 2) +
            Math.pow(nodes[i].y - nodes[j].y, 2) +
            Math.pow(nodes[i].z - nodes[j].z, 2)
        );

        if (distance < 3) {
          lines.push({
            start: new THREE.Vector3(nodes[i].x, nodes[i].y, nodes[i].z),
            end: new THREE.Vector3(nodes[j].x, nodes[j].y, nodes[j].z),
            opacity: 1 - distance / 3,
          });
        }
      }
    }

    return lines;
  }, []);

  useFrame((state) => {
    if (linesRef.current) {
      linesRef.current.rotation.y = state.clock.elapsedTime * 0.02;
      linesRef.current.rotation.x =
        Math.sin(state.clock.elapsedTime * 0.5) * 0.1;
    }
  });

  return (
    <group ref={linesRef}>
      {connections.map((connection, index) => (
        <mesh key={index}>
          <bufferGeometry>
            <bufferAttribute
              attach="attributes-position"
              count={2}
              array={
                new Float32Array([
                  connection.start.x,
                  connection.start.y,
                  connection.start.z,
                  connection.end.x,
                  connection.end.y,
                  connection.end.z,
                ])
              }
              itemSize={3}
            />
          </bufferGeometry>
          <lineBasicMaterial
            color="#00D4FF"
            transparent
            opacity={connection.opacity * 0.3}
          />
        </mesh>
      ))}
    </group>
  );
}

// Main Scene Component
function Scene({
  theme,
  particleCount,
}: {
  theme: string;
  particleCount: number;
}) {
  return (
    <>
      {/* Lighting */}
      <ambientLight intensity={0.2} />
      <pointLight position={[5, 5, 5]} intensity={0.8} color="#00D4FF" />
      <pointLight position={[-5, -5, -5]} intensity={0.6} color="#FF6B35" />

      {/* Particle Systems based on theme */}
      {theme === "trading" && <TradingParticles count={particleCount} />}
      {theme === "data" && <DataFlowParticles count={particleCount} />}
      {theme === "network" && (
        <>
          <TradingParticles count={particleCount / 2} />
          <NetworkConnections />
        </>
      )}

      {/* Controls */}
      <OrbitControls
        enablePan={false}
        enableZoom={true}
        enableRotate={true}
        minDistance={2}
        maxDistance={15}
        autoRotate
        autoRotateSpeed={0.5}
      />
    </>
  );
}

export default function ParticleSystem3D({
  particleCount = 300,
  width = 600,
  height = 400,
  interactive = true,
  theme = "trading",
}: ParticleSystem3DProps) {
  return (
    <div
      className="relative bg-black/10 backdrop-blur-sm rounded-lg border border-accent-cyan/10 overflow-hidden w-full h-full"
      style={{ width: width ?? "100%", height: height ?? "100%" }}
    >
      <Canvas
        camera={{ position: [0, 0, 8], fov: 75 }}
        style={{ width: "100%", height: "100%" }}
      >
        <Scene theme={theme} particleCount={particleCount} />
      </Canvas>

      {/* Overlay UI */}
      <div className="absolute top-4 left-4 text-white">
        <h3 className="text-lg font-orbitron font-bold text-accent-cyan">
          {theme === "trading" && "Sistema de Trading"}
          {theme === "data" && "Flujo de Datos"}
          {theme === "network" && "Red Neuronal"}
        </h3>
        <p className="text-sm text-gray-300">Visualización en tiempo real</p>
      </div>

      {/* Particle count indicator */}
      <div className="absolute bottom-4 left-4 text-xs text-gray-400">
        <p>{particleCount} partículas activas</p>
      </div>

      {interactive && (
        <div className="absolute bottom-4 right-4 text-xs text-gray-400">
          <p>Rotación automática • Scroll para zoom</p>
        </div>
      )}
    </div>
  );
}
